SELECT ?stadium_name ?stadium_location
WHERE {
  {
    SELECT ?stadium_id ?stadium_name ?stadium_location
    WHERE {
      ?concert a :concert ;
               :concert\#year "2014" ;
               :concert\#ref-stadium_id ?stadium .
      ?stadium a :stadium ;
               :stadium\#name ?stadium_name ;
               :stadium\#location ?stadium_location .
    }
  }
  INTERSECT
  {
    SELECT ?stadium_id ?stadium_name ?stadium_location
    WHERE {
      ?concert a :concert ;
               :concert\#year "2015" ;
               :concert\#ref-stadium_id ?stadium .
      ?stadium a :stadium ;
               :stadium\#name ?stadium_name ;
               :stadium\#location ?stadium_location .
    }
  }
}

